pm.test("Status HTTP deve ser 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Resposta deve conter 10 usuários", function () {
    const usuarios = pm.response.json();

    pm.expect(usuarios).to.be.an("array");
    pm.expect(usuarios).to.have.lengthOf(10);
});

pm.test("Cada usuário deve ter id, nome e email", function () {
    const usuarios = pm.response.json();

    usuarios.forEach(function (usuario) {
        pm.expect(usuario).to.have.property("id");
        pm.expect(usuario).to.have.property("name");
        pm.expect(usuario).to.have.property("email");
    });
});

pm.test("Usuário inexistente deve retornar 404", function () {
    pm.response.to.have.status(404);
});

pm.test("Criação deve retornar status 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Resposta deve ser um objeto JSON", function () {
    const usuario = pm.response.json();

    pm.expect(usuario).to.be.an("object");
    pm.expect(usuario).to.have.property("id");
});

pm.test("Resposta deve conter os dados enviados", function () {
    const usuario = pm.response.json();

    pm.expect(usuario.name).to.eql("Kaliana QA");
    pm.expect(usuario.username).to.eql("kaliana_qa");
    pm.expect(usuario.email).to.eql("kaliana.qa@example.com");
});

pm.test("Atualização deve retornar status 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Resposta deve conter o nome atualizado", function () {
    const usuario = pm.response.json();

    pm.expect(usuario.name).to.eql("Kaliana QA Atualizada");
});

pm.test("Resposta deve manter o ID do usuário", function () {
    const usuario = pm.response.json();

    pm.expect(usuario.id).to.eql(1);
});

pm.test("PUT deve retornar status 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Resposta deve conter o nome enviado", function () {
    const usuario = pm.response.json();

    pm.expect(usuario.name).to.eql("Kaliana QA PUT");
});

pm.test("Resposta deve conter username e email enviados", function () {
    const usuario = pm.response.json();

    pm.expect(usuario.username).to.eql("kaliana_put");
    pm.expect(usuario.email).to.eql("kaliana.put@example.com");
});

pm.test("DELETE deve retornar status 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Resposta deve ser um objeto JSON", function () {
    const resposta = pm.response.json();

    pm.expect(resposta).to.be.an("object");
});

pm.test("Resposta não deve indicar erro HTTP", function () {
    pm.expect(pm.response.code).to.be.within(200, 299);
});
